// PriorityQueue.ts

export interface QueueItem<T> {
  id: string;
  priority: number;
  value: T;
  timestamp: number;
}

export class PriorityQueue<T> {
  private heap: QueueItem<T>[];
  private idMap: Map<string, QueueItem<T>>;

  constructor() {
    this.heap = [];
    this.idMap = new Map();
  }

  /**
   * Add an item to the priority queue.
   * @param id Unique identifier for the item
   * @param value The value to store
   * @param priority Higher number = higher priority
   */
  enqueue(id: string, value: T, priority: number): void {
    if (this.idMap.has(id)) {
      throw new Error(`Item with id "${id}" already exists in the queue`);
    }

    const item: QueueItem<T> = {
      id,
      value,
      priority,
      timestamp: Date.now(),
    };

    this.heap.push(item);
    this.idMap.set(id, item);
    this.bubbleUp(this.heap.length - 1);
  }

  /**
   * Remove and return the highest priority item.
   * @returns The item with the highest priority, or undefined if queue is empty
   */
  dequeue(): QueueItem<T> | undefined {
    if (this.heap.length === 0) {
      return undefined;
    }

    const top = this.heap[0];
    const last = this.heap.pop()!;

    if (this.heap.length > 0) {
      this.heap[0] = last;
      this.bubbleDown(0);
    }

    this.idMap.delete(top.id);
    return top;
  }

  /**
   * Peek at the highest priority item without removing it.
   * @returns The item with the highest priority, or undefined if queue is empty
   */
  peek(): QueueItem<T> | undefined {
    return this.heap.length > 0 ? this.heap[0] : undefined;
  }

  /**
   * Remove an item by its unique identifier.
   * @param id The identifier of the item to remove
   * @returns true if the item was found and removed, false otherwise
   */
  removeById(id: string): boolean {
    const item = this.idMap.get(id);
    if (!item) {
      return false;
    }

    const index = this.heap.indexOf(item);
    if (index === -1) {
      // Should not happen if idMap is consistent, but handle gracefully
      this.idMap.delete(id);
      return false;
    }

